        trace.trial_mating_pool_seconds = run_.timing.trial_mating_pool_seconds;
        trace.trial_mating_plan_seconds = run_.timing.trial_mating_plan_seconds;
        trace.trial_pbest_seconds = run_.timing.trial_pbest_seconds;
        trace.trial_mating_select_seconds = run_.timing.trial_mating_select_seconds;
        trace.trial_mutation_seconds = run_.timing.trial_mutation_seconds;
        trace.topology_similarity_cache_hits =
            run_.timing.topology_similarity_cache_hits;
        trace.topology_similarity_cache_misses =
            run_.timing.topology_similarity_cache_misses;
        trace.topology_shape_diff_cache_hits =
            run_.timing.topology_shape_diff_cache_hits;
        trace.topology_shape_diff_cache_misses =
            run_.timing.topology_shape_diff_cache_misses;
        trace.selection_family_gate_seconds = run_.timing.selection_family_gate_seconds;
        trace.selection_compare_seconds = run_.timing.selection_compare_seconds;
        trace.selection_update_seconds = run_.timing.selection_update_seconds;
        trace.selection_basin_seconds = run_.timing.selection_basin_seconds;
        trace.selection_finalize_seconds = run_.timing.selection_finalize_seconds;
        trace.basin_consider_seconds = run_.timing.basin_consider_seconds;
        trace.basin_diversity_match_seconds = run_.timing.basin_diversity_match_seconds;
        trace.basin_distance_seconds = run_.timing.basin_distance_seconds;
        trace.basin_make_elite_seconds = run_.timing.basin_make_elite_seconds;
        trace.basin_trim_seconds = run_.timing.basin_trim_seconds;
        trace.basin_archive_stage_seconds = run_.timing.basin_archive_stage_seconds;
        trace.basin_new_count = run_.timing.basin_new_count;
        trace.basin_replace_count = run_.timing.basin_replace_count;
        trace.basin_trim_count = run_.timing.basin_trim_count;
        trace.dls_iterations = run_.timing.dls_iterations;
        trace.dls_accepted_steps = run_.timing.dls_accepted_steps;
        trace.dls_rejected_steps = run_.timing.dls_rejected_steps;
        trace.dls_jacobian_candidates = run_.timing.dls_jacobian_candidates;
        trace.dls_trial_evaluations = run_.timing.dls_trial_evaluations;
